// Package pop3 implements a minimal RFC 1939 client behind the
// domain.POP3Dialer port. Supports implicit TLS (995), STLS upgrade, and —
// for offline / air-gapped networks — plaintext with optional
// authentication. Policy gating for insecure modes happens in the
// application layer, not here.
package pop3

import (
	"bytes"
	"context"
	"crypto/tls"
	"errors"
	"fmt"
	"io"
	"net"
	"net/textproto"
	"strconv"
	"strings"
	"time"

	"postra/internal/domain"
)

// maxListBytes caps how much of one multi-line response (LIST, UIDL) readList
// may accumulate. Nothing else bounds it: readList collects lines until the
// server sends the terminating ".", and it refreshes the command deadline on
// every line it reads, so a server that keeps dribbling short lines and never
// terminates the response holds the collecting worker for ever with no deadline
// left to stop it. That is worse here than on the IMAP side, where the same
// shape was closed in v0.23.7: readList runs in the enumeration step (the sync
// loop's UIDL, then LIST), so one such maildrop stalls a whole account's sync
// before the first message is touched.
//
// The bound has to clear the biggest legitimate maildrop, which arrives in a
// single response: a UIDL line is a message number, a space and a unique-id of
// at most 70 characters (RFC 1939 §7), charged at 92 bytes per message by
// TestPOP3FullMaildropStaysUnderListBound. 32 MiB therefore leaves room for
// roughly 364,000 messages in one maildrop while still bounding a runaway
// response — 8 MiB, the IMAP figure, would refuse a maildrop of 91,000.
const maxListBytes = 32 << 20

// listLineOverhead is what every line of a multi-line response costs on top of
// the bytes textproto.ReadLine returns, and without it maxListBytes does not
// hold. A line arrives with its CRLF already stripped, so a bare "\r\n" measures
// zero: charging only len(line), a server that answers with nothing but blank
// lines never advances the total at all and readList appends "" for ever, which
// is the runaway the bound exists to stop. A retained line also costs a 16-byte
// string header in lines, so at one byte per line a 32 MiB total would sit on
// far more live heap than the bound suggests. Charging the two bytes the server
// really sent plus that header closes both. The IMAP adapter carries the same
// constant as responseLineOverhead, added for exactly this bypass.
const listLineOverhead = 2 + 16

type Dialer struct{}

func (Dialer) Dial(ctx context.Context, opts domain.POP3DialOptions) (domain.POP3Session, error) {
	addr := net.JoinHostPort(opts.Host, strconv.Itoa(opts.Port))
	connectTO := secondsOr(opts.ConnectTimeoutSec, 15)
	d := &net.Dialer{Timeout: connectTO}

	var conn net.Conn
	var err error
	tlsCfg := &tls.Config{
		ServerName: opts.Host,
		MinVersion: tls.VersionTLS12,
		// #nosec G402 -- offline/self-hosted POP3 servers may use self-signed
		// certs; skipping verification is an explicit per-account opt-in
		// (default false), required by offline-network mail support.
		InsecureSkipVerify: opts.InsecureSkipVerify,
	}
	dialStart := time.Now()
	switch opts.Security {
	case domain.SecurityTLS:
		conn, err = (&tls.Dialer{NetDialer: d, Config: tlsCfg}).DialContext(ctx, "tcp", addr)
	case domain.SecurityStartTLS, domain.SecurityNone:
		conn, err = d.DialContext(ctx, "tcp", addr)
	default:
		return nil, fmt.Errorf("unknown security mode %q", opts.Security)
	}
	if err != nil {
		return nil, connectFailure(err, time.Since(dialStart), connectTO)
	}

	s := &session{
		conn:      conn,
		text:      textproto.NewConn(conn),
		commandTO: secondsOr(opts.CommandTimeoutSec, 60),
	}
	// The greeting gets the connect budget, not the command budget: a server
	// that accepts the connection and never greets (connection limit,
	// middlebox, TLS port addressed in plaintext) is reported in seconds.
	greetStart := time.Now()
	if _, err := s.readGreeting(connectTO); err != nil {
		conn.Close()
		return nil, domain.WrapInbound(domain.StageGreeting, "", fmt.Errorf("pop3 greeting: %w", err), time.Since(greetStart), s.commandTO)
	}

	if opts.Security == domain.SecurityStartTLS {
		stlsStart := time.Now()
		if _, err := s.cmd("STLS"); err != nil {
			conn.Close()
			return nil, fmt.Errorf("STLS: %w", err)
		}
		// TLS is client-speaks-first: after the "+OK" that grants the upgrade a
		// conforming server sends nothing until it has seen the ClientHello. So
		// anything already sitting in the reader is plaintext the server pushed
		// ahead of the handshake — a STARTTLS command injection (CVE-2011-0411
		// and the 2021 "NO STARTTLS" survey), whose payload the upgrade below
		// would otherwise discard along with the old reader, leaving the session
		// to continue as if nothing had happened. Refusing is the safe verdict,
		// and it cannot cost a well-behaved server anything.
		//
		// Best-effort by construction: only bytes that reached this buffer are
		// visible, so an injection still in flight in the kernel or on the wire
		// goes unseen. It narrows the window rather than closing it.
		//
		// The refusal names its own stage like every other failure in this
		// function: reported as a plain error it misses the errors.As in
		// syncDiagnosticStage and the operator is told the TCP connection
		// failed. Only the byte count goes in — never the bytes themselves.
		if n := s.text.R.Buffered(); n > 0 {
			conn.Close()
			refused := fmt.Errorf("STLS: server sent %d bytes before TLS handshake", n)
			return nil, &domain.InboundError{Stage: domain.StageStartTLS, Command: "STLS", Class: domain.ClassifyInbound(refused), Elapsed: time.Since(stlsStart), Timeout: s.commandTO, Err: refused}
		}
		tconn := tls.Client(conn, tlsCfg)
		tlsStart := time.Now()
		if err := tconn.HandshakeContext(ctx); err != nil {
			conn.Close()
			return nil, &domain.InboundError{Stage: domain.StageTLS, Command: "STLS", Class: domain.ClassifyInbound(err), Elapsed: time.Since(tlsStart), Timeout: s.commandTO, Err: fmt.Errorf("STLS handshake: %w", err)}
		}
		s.conn = tconn
		s.text = textproto.NewConn(tconn)
	}

	// Authentication is optional: some maildrops on isolated networks accept
	// sessions without USER/PASS. Only the server's refusal of the
	// credentials is an auth failure; a timeout, a lost connection or a
	// refusal for load ([IN-USE], [LOGIN-DELAY], [SYS/TEMP]) says nothing
	// about the password, and calling it one parks the account in
	// credential_error for good.
	if opts.Username != "" {
		if _, err := s.cmd("USER %s", opts.Username); err != nil {
			s.Close()
			return nil, loginFailure("USER", err)
		}
		pass := ""
		if opts.Password != nil {
			pass = string(opts.Password.Reveal())
		}
		_, err := s.cmd("PASS %s", pass)
		pass = ""
		_ = pass
		if err != nil {
			s.Close()
			return nil, loginFailure("PASS", err)
		}
	}
	return s, nil
}
// Package imap implements a minimal RFC 3501 client behind the
// domain.InboundDialer port (the same port POP3 uses). It covers exactly what
// ingest needs — connect, LOGIN/PREAUTH, SELECT INBOX, enumerate (UID +
// RFC822.SIZE), fetch a message body, and mark-delete + EXPUNGE — and supports
// implicit TLS (993), STARTTLS, and plaintext for offline networks. Policy
// gating for insecure modes stays in the application layer.
package imap

import (
	"bufio"
	"bytes"
	"context"
	"crypto/tls"
	"errors"
	"fmt"
	"io"
	"math"
	"net"
	"regexp"
	"strconv"
	"strings"
	"time"

	"postra/internal/domain"
)

type Dialer struct{}

var (
	reFetch = regexp.MustCompile(`^\* (\d+) FETCH `)
	reUID   = regexp.MustCompile(`UID (\d+)`)
	reSize  = regexp.MustCompile(`RFC822\.SIZE (\d+)`)
	reExist = regexp.MustCompile(`^\* (\d+) EXISTS`)
	reValid = regexp.MustCompile(`UIDVALIDITY (\d+)`)
	reLit   = regexp.MustCompile(`\{(\d+)\}$`)
)

// errUnframed marks a session whose byte stream could no longer be put back in
// frame after a refused literal. Once it is set every command fails with it,
// which is the only safe answer: reading on would hand message bytes to the
// response parser.
var errUnframed = errors.New("imap session abandoned: response stream could not be resynchronized")

func (Dialer) Dial(ctx context.Context, opts domain.InboundDialOptions) (domain.InboundSession, error) {
	addr := net.JoinHostPort(opts.Host, strconv.Itoa(opts.Port))
	connectTO := secondsOr(opts.ConnectTimeoutSec, 15)
	d := &net.Dialer{Timeout: connectTO}
	tlsCfg := &tls.Config{
		ServerName: opts.Host,
		MinVersion: tls.VersionTLS12,
		// #nosec G402 -- offline/self-hosted IMAP servers may use self-signed
		// certs; skipping verification is an explicit per-account opt-in
		// (default false), required by offline-network mail support.
		InsecureSkipVerify: opts.InsecureSkipVerify,
	}

	var conn net.Conn
	var err error
	start := time.Now()
	switch opts.Security {
	case domain.SecurityTLS:
		conn, err = (&tls.Dialer{NetDialer: d, Config: tlsCfg}).DialContext(ctx, "tcp", addr)
	case domain.SecurityStartTLS, domain.SecurityNone:
		conn, err = d.DialContext(ctx, "tcp", addr)
	default:
		return nil, fmt.Errorf("unknown security mode %q", opts.Security)
	}
	if err != nil {
		return nil, connectFailure(err, time.Since(start), connectTO)
	}

	s := &session{conn: conn, r: bufio.NewReader(conn), commandTO: secondsOr(opts.CommandTimeoutSec, 60), maxLiteral: opts.MaxMessageBytes}
	// The greeting is the server's first move and healthy servers send it at
	// once, so it gets the connect budget rather than the command budget. A
	// server that accepts the connection and then says nothing — a per-account
	// connection limit, a middlebox, or a TLS port addressed in plaintext — is
	// then reported in seconds instead of holding a sync slot for a minute.
	start = time.Now()
	_ = conn.SetDeadline(start.Add(connectTO))
	greeting, err := s.readBoundedLine()
	if err != nil {
		conn.Close()
		return nil, s.failed(domain.StageGreeting, "", fmt.Errorf("imap greeting: %w", err), start)
	}
	// Every command sets its own deadline before writing (execRaw), so the
	// greeting's shorter one does not leak into the session.
	preAuth := strings.HasPrefix(greeting, "* PREAUTH")
	if strings.HasPrefix(greeting, "* BYE") {
		// Refused before any command — typically a connection limit.
		conn.Close()
		return nil, s.failed(domain.StageGreeting, "", &domain.InboundRejected{Code: domain.InboundResponseCode(greeting)}, start)
	}

	if opts.Security == domain.SecurityStartTLS {
		starttlsStart := time.Now()
		if _, err := s.exec("STARTTLS"); err != nil {
			conn.Close()
			return nil, fmt.Errorf("STARTTLS: %w", err)
		}
		// TLS is client-speaks-first: after the tagged OK that grants the upgrade
		// a conforming server sends nothing until it has seen the ClientHello. So
		// anything already sitting in the reader is plaintext the server pushed
		// ahead of the handshake — a STARTTLS command injection (CVE-2011-0411
		// and the 2021 "NO STARTTLS" survey), whose payload the upgrade below
		// would otherwise discard along with the old reader, leaving the session
		// to continue as if nothing had happened. Refusing is the safe verdict,
		// and it cannot cost a well-behaved server anything. The POP3 adapter
		// carries the same check on its STLS path.
		//
		// Best-effort by construction: only bytes that reached this buffer are
		// visible, so an injection still in flight in the kernel or on the wire
		// goes unseen. It narrows the window rather than closing it.
		//
		// The refusal names its own stage like every other failure in this
		// function: reported as a plain error it misses the errors.As in
		// syncDiagnosticStage and the operator is told the TCP connection
		// failed. Only the byte count goes in — never the bytes themselves.
		if n := s.r.Buffered(); n > 0 {
			conn.Close()
			refused := fmt.Errorf("STARTTLS: server sent %d bytes before TLS handshake", n)
			return nil, &domain.InboundError{Stage: domain.StageStartTLS, Command: "STARTTLS", Class: domain.ClassifyInbound(refused),
				Elapsed: time.Since(starttlsStart), Timeout: s.commandTO, Err: refused}
		}
		tconn := tls.Client(conn, tlsCfg)
		start = time.Now()
		if err := tconn.HandshakeContext(ctx); err != nil {
			conn.Close()
			return nil, &domain.InboundError{Stage: domain.StageTLS, Command: "STARTTLS", Class: domain.ClassifyInbound(err),
				Elapsed: time.Since(start), Timeout: s.commandTO, Err: fmt.Errorf("STARTTLS handshake: %w", err)}
		}
		s.conn = tconn
		s.r = bufio.NewReader(tconn)
	}

	// IMAP requires authentication before SELECT unless the server greeted
	// with PREAUTH. On offline maildrops "none" refers to transport, not auth.
	if !preAuth && opts.Username != "" {
		pass := ""
		if opts.Password != nil {
			pass = string(opts.Password.Reveal())
		}
		_, err := s.exec("LOGIN %s %s", quote(opts.Username), quote(pass))
		pass = ""
		_ = pass
		if err != nil {
			s.Close()
			// Only the server's refusal of these credentials is an auth
			// failure. A LOGIN that timed out, lost its connection, or was
			// refused for load says nothing about the password, and calling it
			// one parks the account in credential_error for good.
			var rejected *domain.InboundRejected
			if errors.As(err, &rejected) && !domain.TemporaryRefusal(rejected.Code) {
				return nil, &domain.AuthError{Err: fmt.Errorf("LOGIN rejected: %w", err)}
			}
			return nil, fmt.Errorf("LOGIN: %w", err)
		}
	}

	if err := s.selectInbox(); err != nil {
		s.Close()
		return nil, err
	}
	return s, nil
}

